// CODE NODE: CLEAN INTERNAL DATA (REVISI)
const results = [];

for (const item of $input.all()) {
  const json = item.json;

  // 1. Filter Tipe Transaksi
  const tipe = json['Tipe Transaksi'];
  if (tipe !== 'Pembayaran' && tipe !== 'Pengeluaran' && tipe !== 'Penerimaan') {
    continue; 
  }

  // 2. Bersihkan Tanggal (Hapus spasi & format ulang)
  // Asumsi format di CSV/Sheet: DD/MM/YYYY
  const rawDate = (json['Tanggal Transaksi'] || '').toString().trim();
  const dateParts = rawDate.split('/');
  // Pastikan date valid
  if (dateParts.length !== 3) continue;

  const cleanDate = `${dateParts[2]}-${dateParts[1]}-${dateParts[0]}`;

  // 3. PENTING: Bersihkan Angka dari titik (.) atau koma (,)
  // Kita ubah jadi string dulu, hapus semua yang BUKAN angka, baru parse
  const rawAmount = (json['Jumlah (IDR)'] || '0').toString();
  const cleanAmount = parseInt(rawAmount.replace(/[^0-9]/g, ''));

  // 4. Buat Match Key
  const matchKey = `${cleanDate}_${cleanAmount}`;

  results.push({
    json: {
      ...json,
      clean_date: cleanDate,
      clean_amount: cleanAmount,
      match_key: matchKey,
      sumber: 'Internal'
    }
  });
}

return results;

// CODE NODE: CLEAN BANK DATA (EXCEL DATE & STRING FIX)
const results = [];

// Fungsi pembantu konversi serial date Excel ke YYYY-MM-DD
function excelDateToYYYYMMDD(serial) {
  const utc_days = Math.floor(serial - 25569);
  const utc_value = utc_days * 86400;
  const date_info = new Date(utc_value * 1000);

  const year = date_info.getFullYear();
  const month = String(date_info.getMonth() + 1).padStart(2, '0');
  const day = String(date_info.getDate()).padStart(2, '0');

  return `${year}-${month}-${day}`;
}

for (const item of $input.all()) {
  const json = item.json;

  let cleanDate = '';
  const rawDate = json['Tanggal Bank'] ?? json['Tanggal Transaksi'] ?? json['Tanggal'] ?? '';

  // 1. Cek apakah formatnya Angka Serial Excel (contoh: 45956)
  if (typeof rawDate === 'number' || (!isNaN(rawDate) && !String(rawDate).includes('/') && !String(rawDate).includes('-'))) {
    cleanDate = excelDateToYYYYMMDD(Number(rawDate));
  } 
  // 2. Jika formatnya String dengan Garis Miring (DD/MM/YYYY)
  else if (String(rawDate).includes('/')) {
    const parts = String(rawDate).trim().split('/');
    if (parts.length === 3) {
      const year = parts[2].trim();
      const month = parts[1].trim().padStart(2, '0');
      const day = parts[0].trim().padStart(2, '0');
      cleanDate = `${year}-${month}-${day}`;
    }
  } 
  // 3. Jika formatnya String dengan Strip (YYYY-MM-DD atau DD-MM-YYYY)
  else if (String(rawDate).includes('-')) {
    const parts = String(rawDate).trim().split('-');
    if (parts.length === 3) {
      if (parts[0].length === 4) {
        cleanDate = `${parts[0]}-${parts[1].padStart(2, '0')}-${parts[2].padStart(2, '0')}`;
      } else {
        cleanDate = `${parts[2]}-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`;
      }
    }
  }

  // Jika gagal ekstraksi tanggal, skip
  if (!cleanDate) continue;

  // 2. Bersihkan Nominal Angka
  const rawAmount = (json['Jumlah (IDR)'] || json['Nominal'] || '0').toString();
  const cleanAmount = parseInt(rawAmount.replace(/[^0-9]/g, ''), 10) || 0;

  // 3. Buat Match Key
  const matchKey = `${cleanDate}_${cleanAmount}`;

  results.push({
    json: {
      ...json,
      clean_date: cleanDate,
      clean_amount: cleanAmount,
      match_key: matchKey,
      sumber: 'Bank'
    }
  });
}

return results;

// CODE NODE: ANALISA REKONSILIASI LENGKAP (tanpa Union)
const items = $input.all();
const grouped = {};

// 1. Group by match_key
for (const item of items) {
  const key = item.json.match_key;
  if (!grouped[key]) {
    grouped[key] = { sources: [], details: [] };
  }
  grouped[key].sources.push(item.json.sumber);
  grouped[key].details.push(item.json);
}

// 2. Bangun hasil analisa
const results = [];
for (const [key, group] of Object.entries(grouped)) {
  const hasInternal = group.sources.includes('Internal');
  const hasBank = group.sources.includes('Bank');

  let status, pesan, priority;
  if (hasInternal && hasBank) {
    status = 'MATCHED';
    pesan = '✅ Data klop (Cocok).';
    priority = 'Low';
  } else if (hasInternal && !hasBank) {
    status = 'MISSING IN BANK';
    pesan = '⚠️ Tercatat di Internal, tapi tidak ada di Bank.';
    priority = 'High';
  } else if (!hasInternal && hasBank) {
    status = 'UNRECORDED INTERNAL';
    pesan = '⚠️ Ada di Bank, tapi tidak tercatat di Internal.';
    priority = 'Medium';
  }

  const internal = group.details.find(d => d.sumber === 'Internal');
  const bank = group.details.find(d => d.sumber === 'Bank');
  const refDate = (internal || bank)?.clean_date;
  const amount = (internal || bank)?.clean_amount;

  results.push({
    json: {
      Tanggal: refDate,
      Nominal: amount,
      Status: status,
      Pesan: pesan,
      Prioritas: priority,
      Internal_ID: internal?.['ID Referensi'] || 'N/A',
      Bank_ID: bank?.['ID Transaksi Bank'] || 'N/A',
      Deskripsi: internal?.Deskripsi || bank?.['Deskripsi Transaksi'] || '-',
      Match_Key: key,
      Sources: group.sources.join(' + ')
    }
  });
}

return results;

